<!--
 * 消息偏好设置表单组件
 *
 * @path apps/message-web/src/views/preference/preference-form.vue
 * @author ydsz-team
 * @since 1.0.0
 * @modified 4.1.0 由脚手架 CRUD 重写为契约 API：偏好配置表单（PreferenceUpsertDTO）提交 upsert()。
-->
<script lang="ts" setup>
/**
 * 消息偏好（表单组件）
 * <p>消费后端契约 PreferenceController#upsert（src/api/preference.ts，auto-generated by bash/gen-contract.py）：
 * 按 PreferenceUpsertDTO 字段（userId/channel/bizType/enabled/dndEnabled/dndStart/dndEnd/dailyLimit/
 * hourlyLimit/digestEnabled/digestFrequency/locale 等）填写，编辑时回填 MsgPreferenceVO 字段，
 * 提交统一调 upsert(data)（契约仅提供 upsert，无独立 create/update），成功后 emit('success') 并关闭弹窗。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { useYDSZModal } from '@ydsz/common-ui';
import {
  ElForm,
  ElFormItem,
  ElInput,
  ElInputNumber,
  ElMessage,
  ElRadio,
  ElRadioGroup,
  ElSelect,
  ElOption,
} from 'element-plus';
import { computed, reactive, ref } from 'vue';

import { upsert } from '#/api/preference';
import type { MsgPreferenceVO } from '#/api/models';

const emit = defineEmits<{ success: [] }>();

const formRef = ref();
const isEdit = ref(false);

/** 偏好表单状态（字段对应 PreferenceUpsertDTO，enabled 等以 0/1 表示） */
interface PreferenceFormState {
  userId: string;
  channel: string;
  bizType: string;
  enabled: number;
  dndEnabled: number;
  dndStart: string;
  dndEnd: string;
  dailyLimit: number;
  hourlyLimit: number;
  digestEnabled: number;
  digestFrequency: string;
  locale: string;
}

const formData = reactive<PreferenceFormState>({
  userId: 'current',
  channel: '',
  bizType: '',
  enabled: 1,
  dndEnabled: 0,
  dndStart: '',
  dndEnd: '',
  dailyLimit: 0,
  hourlyLimit: 0,
  digestEnabled: 0,
  digestFrequency: '',
  locale: '',
});

const rules = {
  channel: [{ required: true, message: '请输入通道', trigger: 'blur' }],
};

const [Modal, modalApi] = useYDSZModal({
  onOpenChange: (isOpen: boolean) => {
    if (!isOpen) return;
    const data = modalApi.getData<{ record?: MsgPreferenceVO }>();
    if (data?.record) {
      isEdit.value = true;
      Object.assign(formData, {
        userId: data.record.userId ?? 'current',
        channel: data.record.channel ?? '',
        bizType: data.record.bizType ?? '',
        enabled: data.record.enabled ?? 1,
        dndEnabled: data.record.dndEnabled ?? 0,
        dndStart: data.record.dndStart ?? '',
        dndEnd: data.record.dndEnd ?? '',
        dailyLimit: data.record.dailyLimit ?? 0,
        hourlyLimit: data.record.hourlyLimit ?? 0,
        digestEnabled: data.record.digestEnabled ?? 0,
        digestFrequency: data.record.digestFrequency ?? '',
        locale: data.record.locale ?? '',
      });
    } else {
      isEdit.value = false;
      Object.assign(formData, {
        userId: 'current',
        channel: '',
        bizType: '',
        enabled: 1,
        dndEnabled: 0,
        dndStart: '',
        dndEnd: '',
        dailyLimit: 0,
        hourlyLimit: 0,
        digestEnabled: 0,
        digestFrequency: '',
        locale: '',
      });
    }
  },
  onConfirm: async () => {
    try {
      await formRef.value?.validate();
    } catch {
      return;
    }
    modalApi.lock();
    try {
      await upsert({
        userId: formData.userId || undefined,
        channel: formData.channel,
        bizType: formData.bizType || undefined,
        enabled: formData.enabled,
        dndEnabled: formData.dndEnabled,
        dndStart: formData.dndStart || undefined,
        dndEnd: formData.dndEnd || undefined,
        dailyLimit: formData.dailyLimit,
        hourlyLimit: formData.hourlyLimit,
        digestEnabled: formData.digestEnabled,
        digestFrequency: formData.digestFrequency || undefined,
        locale: formData.locale || undefined,
      });
      ElMessage.success(isEdit.value ? '更新成功' : '保存成功');
      emit('success');
      modalApi.close();
    } finally {
      modalApi.unlock();
    }
  },
});

const title = computed(() => (isEdit.value ? '编辑消息偏好' : '新增消息偏好'));
</script>
<template>
  <Modal :title="title">
    <ElForm
      ref="formRef"
      :model="formData"
      :rules="rules"
      label-width="100px"
      label-position="right"
    >
      <ElFormItem label="用户ID" prop="userId">
        <ElInput v-model="formData.userId" placeholder="请输入用户ID" />
      </ElFormItem>
      <ElFormItem label="通道" prop="channel">
        <ElInput v-model="formData.channel" placeholder="请输入通道，如 SMS/EMAIL/IN_APP" />
      </ElFormItem>
      <ElFormItem label="业务类型" prop="bizType">
        <ElInput v-model="formData.bizType" placeholder="请输入业务类型（可为空）" />
      </ElFormItem>
      <ElFormItem label="启用" prop="enabled">
        <ElRadioGroup v-model="formData.enabled">
          <ElRadio :value="1">启用</ElRadio>
          <ElRadio :value="0">停用</ElRadio>
        </ElRadioGroup>
      </ElFormItem>
      <ElFormItem label="免打扰" prop="dndEnabled">
        <ElRadioGroup v-model="formData.dndEnabled">
          <ElRadio :value="1">开启</ElRadio>
          <ElRadio :value="0">关闭</ElRadio>
        </ElRadioGroup>
      </ElFormItem>
      <ElFormItem label="免打扰开始" prop="dndStart">
        <ElInput v-model="formData.dndStart" placeholder="如 22:00（可为空）" />
      </ElFormItem>
      <ElFormItem label="免打扰结束" prop="dndEnd">
        <ElInput v-model="formData.dndEnd" placeholder="如 08:00（可为空）" />
      </ElFormItem>
      <ElFormItem label="每日上限" prop="dailyLimit">
        <ElInputNumber v-model="formData.dailyLimit" :min="0" :max="99999" />
      </ElFormItem>
      <ElFormItem label="每小时上限" prop="hourlyLimit">
        <ElInputNumber v-model="formData.hourlyLimit" :min="0" :max="9999" />
      </ElFormItem>
      <ElFormItem label="摘要订阅" prop="digestEnabled">
        <ElRadioGroup v-model="formData.digestEnabled">
          <ElRadio :value="1">开启</ElRadio>
          <ElRadio :value="0">关闭</ElRadio>
        </ElRadioGroup>
      </ElFormItem>
      <ElFormItem label="摘要频率" prop="digestFrequency">
        <ElSelect
          v-model="formData.digestFrequency"
          placeholder="请选择摘要频率（可为空）"
          clearable
        >
          <ElOption label="每天" value="DAILY" />
          <ElOption label="每周" value="WEEKLY" />
          <ElOption label="每月" value="MONTHLY" />
        </ElSelect>
      </ElFormItem>
      <ElFormItem label="语言" prop="locale">
        <ElInput v-model="formData.locale" placeholder="请输入语言（可为空）" />
      </ElFormItem>
    </ElForm>
  </Modal>
</template>
